insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-07','verbeterd','Relaties','Betaaltermijn staat nu bij de relatie',
   'De betaaltermijn die in Bouw7 bij een klant is afgesproken, staat nu ook in EVA op de relatiekaart. Bij 150 relaties is die in één keer ingevuld, en hij loopt voortaan automatisch mee. Pas je hem in EVA met de hand aan, dan blijft jouw waarde staan.'),
  ('2026-09-07','opgelost','Relaties','Contactpersonen lopen weer mee, inclusief aanhef',
   'Contactpersonen werden al een tijd niet meer bijgewerkt vanuit Bouw7, waardoor er 71 ontbraken en e-mailadressen en telefoonnummers achterliepen. Dat is verholpen. Meteen is ook de aanhef overgenomen: bij 147 contactpersonen staat nu of het een heer of een mevrouw is, zodat offertes en brieven de juiste aanhef krijgen in plaats van "Geachte heer/mevrouw". Bij VvE''s en servicedesks blijft dat veld bewust leeg.');
